def spiral_order(grid):
    """Return the elements of a 2D grid in clockwise spiral order, starting at the
    top-left corner, seen across the top, down the right, back along the bottom,
    and up the left, repeating this inward until every cell is visited once.
    An empty or columnless grid gives an empty list."""
    if not grid or not grid[0]:
        return []
    res = []
    top, bottom, left, right = 0, len(grid) - 1, 0, len(grid[0]) - 1
    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            res.append(grid[top][col])
        top += 1
        for row in range(top, bottom + 1):
            res.append(grid[row][right])
        right -= 1
        if top <= bottom:
            for col in range(right, left - 1, -1):
                res.append(grid[bottom][col])
            bottom -= 1
        if left <= right:
            for row in range(bottom, top - 1, -1):
                res.append(grid[row][left])
            left += 1
    return res
```

