from collections import deque
from typing import List

def count_islands(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))

    def bfs(x, y):
        queue = deque([(x, y)])
        while queue:
            i, j = queue.popleft()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj] and grid[ni][nj] == 1:
                    queue.append((ni, nj))

    count = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                # Could use either DFS or BFS here, both are valid
                # bfs(i, j)
                dfs(i, j)
                count += 1

    return count
```

