def increment_semver(version, part):
    def apply_change(v, at_index):
        parts = list(map(int, v.split('.')))
        part_value = parts[at_index] + 1
        for i in range(at_index + 1, 3):
            parts[i] = 0
        parts[at_index] = part_value
        return '.'.join(map(str, parts))
    return apply_change(version, 0 if part == 'major' else 1 if part == 'minor' else 2)
```

