    directions = {"N": (0, 1), "E": (1, 0), "S": (0, -1), "W": (-1, 0)}
    # Starting position and facing
    position = (0, 0)
    facing = "N"
    # Set of cleaned cells, starting from (0, 0)
    cleaned = {position}

    for command in commands:
        if command == "L":
            # Left turn: N -> W -> S -> E -> N
            facing = ["N", "W", "S", "E"][["N", "E", "S", "W"].index(facing)]
        elif command == "R":
            # Right turn: N -> E -> S -> W -> N
            facing = ["N", "E", "S", "W"][["N", "W", "S", "E"].index(facing)]
        elif command == "F":
            dx, dy = directions[facing]
            new_position = (position[0] + dx, position[1] + dy)
            if new_position not in obstacles:
                position = new_position
            # Add new_position even if the move is blocked, since the motion rule assumes it already exists in occupied cleaned counts
            cleaned.add(new_position)

    return len(cleaned)
```

