def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    red_ticks = set(range(0, red_duration))
    crossing = []
    for arrival in arrivals:
        while True:
            if arrival <= len(crossing):
                # If the pedestrian arrives before the next red interval starts
                if len(crossing) % (red_duration + green_duration) < red_duration:
                    crossing.append(len(crossing))
                else:
                    # Skip into the start of the next red interval
                    len(crossing) += red_duration + green_duration
                    crossing.append(len(crossing))
                break
            else:
                # Skip ticks the pedestrian arrived after
                len(crossing) = arrival
    return crossing
```

