def _rotate(g, d):
    h, w = len(g), len(g[0])
    if d == 0:
        return _equal(g, g)
    if d == 90:
        return _equal([[g[h - j - 1][i] for j in range(h)] for i in range(w)], g)
    if d == 180:
        return _equal([[g[h - i - 1][w - j - 1] for j in range(w)] for i in range(h)], g)
    if d == 270:
        return _equal([[g[j][w - i - 1] for j in range(h)] for i in range(w)], g)
    raise ValueError(f"invalid rotation {d}")
