def count_islands(grid):
    if not grid or not grid[0]:
        return 0
    visited = set()
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                # Expand from (r,c) and mark every cell of that island
                visited.add((r, c))
                from collections import deque
                q = deque()
                q.append((r, c))
                while q:
                    x, y = q.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        if 0 <= x + dx < rows and 0 <= y + dy < cols:
                            nx, ny = x + dx, y + dy
                            if grid[nx][ny] == 1 and (nx, ny) not in visited:
                                visited.add((nx, ny))
                                q.append((nx, ny))
    return len(visited)
```

The function marks each island by depth-first or breadth-first search from its first unvisited 1-cell, then returns the number of disjoint 1-cells reached this way. Each cell belongs to at most one island.

