        elif typ == 'withdraw':
            name, amt = args
            from_amounts[name] = from_amounts.get(name, 0) + amt
        elif typ == 'transfer':
            from_name, to_name, amt = args
            from_amounts[from_name] = from_amounts.get(from_name, 0) + amt
            to_amounts[to_name] = to_amounts.get(to_name, 0) + amt
    result = {}
