def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    result = []
    if direction == 1:
        end = top_floor
        first_floor = min(requests or [top_floor])
    else:
        end = 1
        first_floor = max(requests or [1]) if requests else 1
    while start_floor != end:
        if start_floor in requests:
            result.append(start_floor)
        start_floor += direction
    if start_floor in requests or not requests:
        result.append(start_floor)
